const DUBAI_OFFSET_MS = 4 * 60 * 60 * 1000; // UTC+4, no DST
const input = ($input.first() && $input.first().json) || {};
const now = input.date ? new Date(input.date) : new Date();
const dubai = new Date(now.getTime() + DUBAI_OFFSET_MS);

const year = dubai.getUTCFullYear();
const month = dubai.getUTCMonth() + 1;
const day = dubai.getUTCDate();
const budgetMonth = `${year}-${String(month).padStart(2, "0")}`;

const prev = new Date(Date.UTC(year, month - 2, 1));
const previousBudgetMonth = `${prev.getUTCFullYear()}-${String(prev.getUTCMonth() + 1).padStart(2, "0")}`;

return [{
  json: { isoDate: now.toISOString(), dubaiYear: year, dubaiMonth: month, dubaiDay: day, budgetMonth, previousBudgetMonth },
}];
